      return { lTipOn: true, lTipX: cx.toFixed(1), lTipTitle: ymTxt(t), lTipRows: rows, lTipDots: rows.map((r) => ({ cx: cx.toFixed(1), cy: r.cy.toFixed(1), color: r.color })),
        lTipStyle: 'position:absolute;top:6px;pointer-events:none;z-index:2;min-width:180px;padding:10px 12px;border-radius:12px;background:var(--surface);border:1px solid var(--outline);box-shadow:0 6px 18px rgba(0,0,0,.18);display:flex;flex-direction:column;gap:5px;left:' + (cx / 640 * 100).toFixed(2) + '%;transform:' + (cx > 380 ? 'translateX(calc(-100% - 14px))' : 'translateX(14px)') };
